#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {        int n;        cin >> n;        vector<int> a(n);        for(int i=0;i<n;i++)        {            cin >> a[i];        }        vector<int> co(a.begin(),a.end());        sort(co.begin(),co.end());        bool found = true;        for(int i=0;i<n;i++)        {            if(co[i] != a[i])            {                found = false;                break;            }        }        if(found)        {            cout << a.size() << endl;        }        else        {            cout << 1 << endl;        }    }}